def build_path(graph, start, end, visited):
    path = []
    while end != start:
        path.append(end)
        for neighbor, weight in graph[end]:
            if visited[end - 1] + weight == graph[end - 1][neighbor - 1]:
                end = neighbor
                break
        else:
            return None
    path.append(start)
    path.reverse()
    return path
